object DropAddZero extends Transformer {
  override def apply(tree: Tree): Tree = {
    val t = super.apply(tree)                 // engine: recurse, then rewrite
    t match {
      case Term.ApplyInfix(lhs, Term.Name("+"), _, List(Lit.Int(0))) => lhs
      case other => other                     // x + 0 -> x
    }
  }
}

